// ForkJSONBody defines parameters for Fork.
type ForkJSONBody struct {
	// Env Replaces the env the fork would otherwise inherit from the source sandbox. Same validation rules as `CreateSandboxRequest.env`.
	Env *map[string]string `json:"env,omitempty"`

	// Environment Optionally pin the fork to a different named sandbox environment. Omit to inherit the source sandbox's environment. Unknown names are rejected with `unknown_environment`.
	//
	// Examples: base, customer-demos
	Environment *string `json:"environment,omitempty"`

	// FailFast Pass `true` to fork only if a machine is ready right now. Within about 1.5 s you get the usual `202`, or `503` `no_ready_machine` with no fork created and nothing counted against your start limits.
	FailFast *bool `json:"failFast,omitempty"`

	// Labels Labels of the fork. The fork never takes the source's labels. Same rules as `CreateSandboxRequest.labels`.
	Labels *map[string]string `json:"labels,omitempty"`

	// Monitoring `false` creates the fork with monitoring off: Boat keeps no command or process output, process list or CPU/RAM samples for it. Omitted, the fork keeps the source sandbox's setting. `true` turns it on for the fork, unless the account has monitoring off by default (`409` `monitoring_off_for_account`).
	Monitoring *bool `json:"monitoring,omitempty"`

	// NoEnv Make the fork no-env (see `CreateSandboxRequest.noEnv`). A fork of a no-env sandbox is always no-env regardless of this field.
	NoEnv *bool `json:"noEnv,omitempty"`

	// TTLSeconds Auto-stop for the fork, in seconds. Omit for the 1 hour default; the fork does NOT inherit the source sandbox's TTL, so forking a sandbox that has auto-stop disabled still gives you a fork that stops itself. `null` disables auto-stop, which means nothing will ever stop this sandbox for you.
	TTLSeconds *int `json:"ttlSeconds,omitempty"`

	// Type Machine size for the fork. Omit to inherit the source sandbox's type. `xlarge` needs the $100/month plan or higher (403 `machine_class_plan_required`). The source sandbox is never modified. Shrinking is rejected with `type_too_small` when the source's data would not fit the smaller disk.
	Type *ForkJSONBodyType `json:"type,omitempty"`
}

